    Z='Z'
    H=G+[Z]
    S={}
    for a in H:
        for b in H:
            if a==Z: S[a,b]={b}; continue
            if b==Z: S[a,b]={a}; continue
            r=set()
            if a==b:
                r.add(Z)
                for c in G:
                    if c!=a and add(c,neg(a)) in Ds: r.add(c)
            else:
                for c in G:
                    if c!=a and c!=b and add(add(a,b),c) in Ks: r.add(c)
                # degenerate {a,a,b}: b in a⊞a iff b-a in D ; then a in a⊞b, and b in b⊞b? no: triple {a,a,b} gives a∈a⊞b
                if add(b,neg(a)) in Ds: r.add(a)
                if add(a,neg(b)) in Ds: r.add(b)
            S[a,b]=r
    return G,H,S,add,Z
def sset(S,A,B):
    r=set()
    for a in A:
        for b in B: r|=S[a,b]
    return r
def check(G,H,S,Z):
    for a in H:
        for b in H:
            if not S[a,b]: return 'empty'
            if S[a,b]!=S[b,a]: return 'comm'
    for a in H:
        for b in H:
            for c in H:
                if sset(S,S[a,b],{c})!=sset(S,{a},S[b,c]): return ('assoc',a,b,c)
    return 'ok'
def claim(G,H,S,add,Z):
    one=G[0]
    for x in G:
        for y in G:
            if one in S[x,y]:
                x3=add(add(x,x),x); y3=add(add(y,y),y); xy=add(x,y)
                T=sset(S,sset(S,sset(S,sset(S,{x3},{y3}),{xy}),{xy}),{xy})
                if one not in T: return (x,y)
    return None
