import sys; sys.path.insert(0,'/tmp/hf4')
from gf import make_field
from orb import orbits
import itertools
def run(k,mstep,limit=None):
    q,add,neg,zero,mul,pw,log=make_field(k)
    orbs=orbits(k,mstep)
    # exclude {a,a,a}
    orbs=[o for o in orbs if not (o[0][0]==o[0][1]==o[0][2])]
    n=len(orbs); print('k',k,'orbits',n); sys.stdout.flush()
    # for each orbit, contributions to S_g: triples containing 0
    contrib=[]
    for o in orbs:
        c=[]
        for t in o:
            t=list(t)
            if zero in t:
                t2=t[:]; t2.remove(zero); g,h=t2
                c.append((g,h)); c.append((h,g))
        contrib.append(set(c))
    sub=lambda a,b: add[a][neg[b]]
    G=list(range(q))
    def tr(mask,c):
        r=0
        m=mask
        while m:
            lb=m&-m; i=lb.bit_length()-1; r|=1<<add[i][c]; m^=lb
        return r
    found=[]
    cnt=0
    for bits in range(1,1<<n):
        S=[0]*q
        for i in range(n):
            if bits>>i&1:
                for g,h in contrib[i]: S[g]|=1<<h
        if any(S[g]==0 for g in G if g!=zero): continue
        D=S[zero]
        if D==0: continue
        Q=1<<zero
        for d in G:
            if D>>d&1: Q|=S[d]
        bad=False
        for x in G:
            if x==zero: continue
            ws=tr(S[x],x)  # x + S_x
            for w in G:
                if ws>>w&1 and (Q & tr(Q,w))==0:
                    bad=True;break
            if bad: break
        if not bad: continue
        cnt+=1
        # 4-point
        P={}
        for c in G:
            for e in G:
                P[c,e]=tr(S[sub(e,c)],c)
        ok=True
        for b in G:
            Sb=S[b]
            for c in G:
                for e in G:
                    r1=(b==zero and c==e) or (Sb & P[c,e])!=0
                    r2=(c==zero and b==e) or (S[c] & P[b,e])!=0
                    if r1!=r2: ok=False;break
                if not ok: break
            if not ok: break
        if ok:
            print('FOUND',bits); found.append(bits); sys.stdout.flush()
    print('claim-failing candidates',cnt,'found',len(found))
    return found
if __name__=='__main__':
    run(int(sys.argv[1]),int(sys.argv[2]))
